@Test
public void scriptingUpdate() {
    CamelRouteTO oldRoute = camelRouteService.read(AnyTypeKind.USER, "createUser");
    // updating route content including new attribute management
    String routeContent = "" + "  <route id=\"createUser\">\n" + "    <from uri=\"direct:createUser\"/>\n" + "    <setProperty propertyName=\"actual\">\n" + "      <simple>${body}</simple>\n" + "    </setProperty>\n" + "    <setBody>\n" + "     <groovy>\n" + "request.body.getPlainAttr(\"camelAttribute\").get().getValues().set(0,\"true\")\n" + "       return request.body\n" + "     </groovy>\n" + "    </setBody>\n" + "    <doTry>\n" + "      <bean ref=\"uwfAdapter\" method=\"create(${body},${exchangeProperty.disablePwdPolicyCheck},\n" + "                                     ${exchangeProperty.enabled})\"/>\n" + "      <to uri=\"propagate:create?anyTypeKind=USER\"/>\n" + "      <to uri=\"direct:createPort\"/>\n" + "      <doCatch>        \n" + "        <exception>java.lang.RuntimeException</exception>\n" + "        <handled>\n" + "          <constant>false</constant>\n" + "        </handled>\n" + "        <to uri=\"direct:createPort\"/>\n" + "      </doCatch>\n" + "    </doTry>\n" + "  </route> ";
    try {
        doUpdate(AnyTypeKind.USER, "createUser", routeContent);
        // creating new schema attribute for user
        PlainSchemaTO schemaTO = new PlainSchemaTO();
        schemaTO.setKey("camelAttribute");
        schemaTO.setType(AttrSchemaType.String);
        createSchema(SchemaType.PLAIN, schemaTO);
        AnyTypeClassTO typeClass = new AnyTypeClassTO();
        typeClass.setKey("camelAttribute");
