@Test
public void pushUnmatchingUsers() throws Exception {
    assertFalse(userService.read("74cd8ece-715a-44a4-a736-e17b46c4e7e6").getResources().contains(RESOURCE_NAME_TESTDB2));
    assertFalse(userService.read("b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee").getResources().contains(RESOURCE_NAME_TESTDB2));
    assertFalse(userService.read("c9b2dec2-00a7-4855-97c0-d854842b4b24").getResources().contains(RESOURCE_NAME_TESTDB2));
    assertTrue(userService.read("823074dc-d280-436d-a7dd-07399fae48ec").getResources().contains(RESOURCE_NAME_TESTDB2));
    JdbcTemplate jdbcTemplate = new JdbcTemplate(testDataSource);
    assertEquals(0, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='puccini'").size());
    // ------------------------------------------
    // Unmatching --> Assign --> dryRuyn
    // ------------------------------------------
    execProvisioningTask(taskService, TaskType.PUSH, "af558be4-9d2f-4359-bf85-a554e6e90be1", 50, true);
    assertEquals(0, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='vivaldi'").size());
    assertFalse(userService.read("b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee").getResources().contains(RESOURCE_NAME_TESTDB2));
    // ------------------------------------------
    Set<String> pushTaskKeys = new HashSet<>();
    pushTaskKeys.add("af558be4-9d2f-4359-bf85-a554e6e90be1");
    pushTaskKeys.add("97f327b6-2eff-4d35-85e8-d581baaab855");
    pushTaskKeys.add("03aa2a04-4881-4573-9117-753f81b04865");
    pushTaskKeys.add("5e5f7c7e-9de7-4c6a-99f1-4df1af959807");
    execProvisioningTasks(taskService, TaskType.PUSH, pushTaskKeys, 50, false);
    // ------------------------------------------
    // Unatching --> Ignore
    // ------------------------------------------
    assertEquals(1, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='verdi'").size());
    assertFalse(userService.read("74cd8ece-715a-44a4-a736-e17b46c4e7e6").getResources().contains(RESOURCE_NAME_TESTDB2));
    // ------------------------------------------
    // ------------------------------------------
    // Unmatching --> Assign
    // ------------------------------------------
    assertEquals(1, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='vivaldi'").size());
    assertTrue(userService.read("b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee").getResources().contains(RESOURCE_NAME_TESTDB2));
    jdbcTemplate.execute("DELETE FROM test2 WHERE ID='vivaldi'");
    // ------------------------------------------
    // ------------------------------------------
    // Unmatching --> Provision
    // ------------------------------------------
    assertEquals(1, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='bellini'").size());
    assertFalse(userService.read("c9b2dec2-00a7-4855-97c0-d854842b4b24").getResources().contains(RESOURCE_NAME_TESTDB2));
    jdbcTemplate.execute("DELETE FROM test2 WHERE ID='bellini'");
    // ------------------------------------------
    // ------------------------------------------
    // Unmatching --> Unlink
    // ------------------------------------------
    assertEquals(0, jdbcTemplate.queryForList("SELECT ID FROM test2 WHERE ID='puccini'").size());
    assertFalse(userService.read("823074dc-d280-436d-a7dd-07399fae48ec").getResources().contains(RESOURCE_NAME_TESTDB2));
    // ------------------------------------------
}

@Test
public void pushMatchingUser() throws Exception {
    assertTrue(userService.read("1417acbe-cbf6-4277-9372-e75e04f97000").getResources().contains(RESOURCE_NAME_TESTDB2));
